const contacts = $input.all().map(i => i.json);
if (!contacts.length || !contacts[0].id) return [{ json: { error: 'No data' } }];

// Build conversion model from historical data
const converted = contacts.filter(c => c.converted);
const notConverted = contacts.filter(c => !c.converted);

// Calculate feature importance (simplified logistic-like scoring)
const features = {};

// Source conversion rates
const sourceRates = {};
for (const c of contacts) {
  if (!sourceRates[c.source]) sourceRates[c.source] = { total: 0, converted: 0 };
  sourceRates[c.source].total++;
  if (c.converted) sourceRates[c.source].converted++;
}
for (const [source, data] of Object.entries(sourceRates)) {
  features[`source_${source}`] = data.total > 5 ? data.converted / data.total : 0;
}

// Activity thresholds from converted contacts
const avgConvertedActivities = converted.length > 0 
  ? converted.reduce((s, c) => s + (parseInt(c.total_activities) || 0), 0) / converted.length 
  : 10;
const avgConvertedEmails = converted.length > 0
  ? converted.reduce((s, c) => s + (parseInt(c.emails_opened) || 0), 0) / converted.length
  : 5;
const avgConvertedMeetings = converted.length > 0
  ? converted.reduce((s, c) => s + (parseInt(c.meetings) || 0), 0) / converted.length
  : 1;

// Score all non-converted contacts
const predictions = contacts.filter(c => !c.converted && c.lead_status !== 'customer').map(c => {
  let predictedScore = 0;

  // Source weight (0-20)
  const sourceRate = sourceRates[c.source]?.converted / sourceRates[c.source]?.total || 0;
  predictedScore += sourceRate * 20;

  // Activity engagement (0-25)
  const activityRatio = Math.min(1, (parseInt(c.total_activities) || 0) / avgConvertedActivities);
  predictedScore += activityRatio * 25;

  // Email engagement (0-20)
  const emailRatio = Math.min(1, (parseInt(c.emails_opened) || 0) / Math.max(1, avgConvertedEmails));
  predictedScore += emailRatio * 20;

  // Meeting indicator (0-15)
  const meetingRatio = Math.min(1, (parseInt(c.meetings) || 0) / Math.max(1, avgConvertedMeetings));
  predictedScore += meetingRatio * 15;

  // Recency (0-10)
  const recencyRatio = Math.min(1, (parseInt(c.activities_7d) || 0) / 3);
  predictedScore += recencyRatio * 10;

  // Company/job title bonus (0-10)
  if (c.company) predictedScore += 3;
  if (c.job_title) predictedScore += 3;
  if (c.custom_fields?.company_size && parseInt(c.custom_fields.company_size) > 50) predictedScore += 4;

  return {
    contact_id: c.id,
    current_score: c.lead_score,
    predicted_score: Math.round(Math.min(100, predictedScore)),
    conversion_probability: Math.round(Math.min(95, predictedScore * 0.95)),
    score_diff: Math.round(Math.min(100, predictedScore)) - (c.lead_score || 0),
    top_signals: [
      activityRatio > 0.7 ? 'High activity' : null,
      emailRatio > 0.7 ? 'Strong email engagement' : null,
      meetingRatio > 0.5 ? 'Meeting booked' : null,
      recencyRatio > 0.7 ? 'Recent engagement' : null,
      sourceRate > 0.3 ? `High-converting source (${c.source})` : null
    ].filter(Boolean)
  };
}).sort((a, b) => b.predicted_score - a.predicted_score);

return [{
  json: {
    model_stats: {
      total_contacts: contacts.length,
      converted: converted.length,
      conversion_rate: Math.round(converted.length / contacts.length * 100),
      avg_converted_activities: Math.round(avgConvertedActivities),
      avg_converted_emails: Math.round(avgConvertedEmails)
    },
    top_predictions: predictions.slice(0, 20),
    score_updates: predictions.filter(p => Math.abs(p.score_diff) >= 10).slice(0, 50),
    generated_at: new Date().toISOString()
  }
}];
